def n_queens(n):
    cols, diag, anti = set(), set(), set()

    def place(row):
        if row == n:
            return 1
        count = 0
        for c in range(n):
            if c in cols or row - c in diag or row + c in anti:
                continue                      # attacked: prune
            cols.add(c); diag.add(row - c); anti.add(row + c)
            count += place(row + 1)
            cols.remove(c); diag.remove(row - c); anti.remove(row + c)
        return count

    return place(0)


def subset_sum(xs, target):
    xs = sorted(xs)

    def walk(i, total):
        if total == target:
            return True
        if i == len(xs) or total + xs[i] > target:
            return False                      # sorted: nothing later fits
        return walk(i + 1, total + xs[i]) or walk(i + 1, total)

    return walk(0, 0)
